def add_mo_dau_v2(doc, h_chap, h_sec, h_sub, p_body, p_bullet, add_table_data, add_figure=None):
    h_chap(doc, "MỞ ĐẦU")
    
    h_sec(doc, "1. Lý do chọn đề tài và bối cảnh chuyển dịch công nghệ 2026")
    p_body(doc, "Kỷ nguyên công nghệ số năm 2026 đang chứng kiến sự hội tụ bùng nổ chưa từng có giữa các phân nhánh trụ cột của Trí tuệ Nhân tạo (Artificial Intelligence - AI). Nếu như trong thập niên 2012–2021, tâm điểm của cuộc cách mạng tập trung vào Học sâu (Deep Learning) với khả năng trích xuất đặc trưng tự động trên các miền dữ liệu cảm quan phi cấu trúc như hình ảnh (thông qua Mạng nơ-ron tích chập - CNN) hay chuỗi thời gian tuần tự (thông qua Mạng nơ-ron hồi quy - RNN, LSTM, GRU); thì từ năm 2022 đến 2026, làn sóng Mô hình Nền tảng (Foundation Models), Đồ thị Tri thức (Knowledge Graphs - KG), Truy hồi Tăng cường Tạo sinh (Retrieval-Augmented Generation - RAG) và đặc biệt là Hệ Đa Tác tử Tự chủ (Autonomous Multi-Agent Systems - MAS) đã tái định hình căn bản cách nhân loại thiết kế và vận hành các hệ thống thông minh.")
    p_body(doc, "Bối cảnh thực thi công nghệ năm 2026 đặt ra hai biến chuyển mang tính lịch sử:")
    p_bullet(doc, "Đạo luật Trí tuệ Nhân tạo toàn cầu (EU AI Act và Dự thảo Luật Công nghiệp Công nghệ số Việt Nam 2026) chính thức áp đặt các rào cản pháp lý và an toàn nghiêm ngặt đối với các hệ thống AI có rủi ro cao (High-risk AI systems), đặc biệt là trong lĩnh vực Y tế và Tài chính. Các mô hình hộp đen (Black-box models) không có căn cứ giải thích (Explainability), dễ bị ảo giác tri thức (Hallucination) hoặc tiềm ẩn nguy cơ sai lệch độc hại (Toxicity) đều bị từ chối cấp phép vận hành thương mại.", "Thách thức Pháp lý & Đạo đức AI:")
    p_bullet(doc, "Thị trường tài chính Việt Nam bước vào giai đoạn quyết định nâng hạng thị trường mới nổi theo tiêu chuẩn FTSE Russell vào tháng 9/2026, đòi hỏi các định chế tài chính, ngân hàng thương mại và quỹ đầu tư phải sở hữu các hệ thống quản trị rủi ro định lượng tự động, minh bạch, có khả năng xử lý dữ liệu phi cấu trúc theo thời gian thực và tự động phát hiện gian lận giao dịch với độ trễ thấp.", "Áp lực Chuyển dịch Định lượng Tài chính:")
    p_body(doc, "Tuy nhiên, trong thực tiễn đào tạo và nghiên cứu kỹ thuật hiện nay, một khoảng cách nghiêm trọng thường xuyên tồn tại: các phân vùng tri thức AI bị phân mảnh và cô lập (Siloed AI). Kỹ sư dữ liệu tập trung vào học máy bảng truyền thống (Tabular ML); chuyên gia thị giác máy tính tách biệt trong không gian CNN; chuyên gia kinh tế lượng chỉ sử dụng các mô hình chuỗi thời gian thống kê; trong khi các kỹ sư phát triển phần mềm hiện đại lại phụ thuộc hoàn toàn vào các lệnh gọi API từ các mô hình ngôn ngữ lớn thương mại mà bỏ qua các nguyên lý toán học nền tảng, cơ chế lan truyền ngược (backpropagation), thiên kiến quy nạp (inductive bias) và các kiểm chứng parity toán học.")
    p_body(doc, "Xuất phát từ tư tưởng cốt lõi xuyên suốt chương trình đào tạo của PGS. TS. Trần Đình Quế tại Học viện Công nghệ Bưu chính Viễn thông: 'Hiểu bản chất hệ thống, biểu diễn tường minh thông tin, học mối quan hệ từ dữ liệu thực tế và biến mô hình thành ứng dụng hoàn chỉnh có thể kiểm chứng được', đề tài tiểu luận này được xây dựng nhằm mục tiêu kết nối toàn diện và liền mạch toàn bộ các tầng bậc tiến hóa của Trí tuệ Nhân tạo. Hệ thống được triển khai trên hai miền ứng dụng thực tiễn mang tính sống còn và đòi hỏi độ chính xác khắt khe bậc nhất: (1) Chăm sóc Sức khỏe Chuyển hóa & Bệnh mạn tính (Metabolic Healthcare) và (2) Kinh tế & Định lượng Tài chính Đa thị trường (Quantitative Finance & Risk Management).")

    h_sec(doc, "2. Mục tiêu nghiên cứu và phạm vi khoa học")
    p_body(doc, "Công trình nghiên cứu hướng tới các mục tiêu khoa học cụ thể và chuẩn mực sau:")
    p_bullet(doc, "Làm chủ trọn vẹn cơ sở toán học và cơ chế giải tích từ các thuật toán Học máy cơ bản (OLS, Ridge, Logistic Regression, SVM KKT, XGBoost Taylor bậc 2, MLP), Mạng tích chập CNN (toán học 2D conv, im2col, Receptive Field, Grad-CAM), Mạng hồi quy RNN/LSTM (BPTT, CEC error carousel, Temporal Attention), Đồ thị Tri thức (RDF/OWL, Hybrid RAG, GraphRAG), Học sâu trên đồ thị (MPNN, Spectral GCN, GraphSAGE, GAT, Over-smoothing Dirichlet) đến Hệ Đa Tác tử tự chủ (Dec-POMDP, CTDE, Bayesian Consensus Gate, 4-Tier Guardrails).", "Làm chủ Bản chất Toán học:")
    p_bullet(doc, "Triển khai độc lập các kiến trúc mạng nơ-ron nền tảng (MLP, CNN 6 tầng, LSTM 6 tầng) trên 3 phương pháp hoàn toàn khác nhau: (1) Tự lập trình từ đầu bằng thuần NumPy Scratch (bao gồm cả forward pass và analytic backpropagation), (2) Khung Keras/TensorFlow cấp cao, và (3) Khung PyTorch hướng nghiên cứu. Thiết lập quy trình kiểm chứng sai lệch đạo hàm tuyệt đối (Gradient Parity Check) với ngưỡng dung sai cực đại không vượt quá 10^-7.", "Thực thi Tam Khung & Kiểm chứng Parity:")
    p_bullet(doc, "Nghiên cứu và biểu diễn toàn bộ các mô hình học máy, mạng nơ-ron và chu trình đa tác tử dưới một lăng kính toán học thống nhất: Nguyên lý Hợp các hàm toán học f(x) = (f_L o ... o f_1)(x), chỉ rõ dạng tensor đầu vào, không gian ẩn và đầu ra tại từng mắt xích chuyển đổi.", "Nguyên lý Hợp các hàm toán học:")
    p_bullet(doc, "Xây dựng các hệ thống kiểm thử thực tế không nhìn trước (No-lookahead backtest), tính toán đầy đủ chi phí giao dịch, thuế, trượt giá và độ trễ khớp lệnh; đánh giá hệ thống y tế theo các tiêu chuẩn lâm sàng quốc tế (Clarke Error Grid 100% vùng A+B, Ragas Tri-metrics).", "Định lượng Thực tế & Khắc phục Rò rỉ:")
    p_bullet(doc, "Đóng gói toàn bộ kết quả nghiên cứu thành 7 ứng dụng Web tương tác hoàn chỉnh chạy trên môi trường cục bộ (Localhost Web Demos), kết nối trực quan với mã nguồn trong các sổ tay Jupyter Notebook thực nghiệm.", "Trực quan hóa & Triển khai Thực tế:")

    h_sec(doc, "3. Bảy câu hỏi nghiên cứu cốt lõi (CH1 – CH7)")
    p_body(doc, "Để định hình logic khoa học chặt chẽ và nhất quán xuyên suốt 7 chương chuyên môn, tiểu luận đặt ra và giải quyết triệt để 7 câu hỏi nghiên cứu trọng tâm sau:")
    p_bullet(doc, "Lịch sử hơn 70 năm phát triển của Trí tuệ Nhân tạo đã trải qua những chu kỳ hưng thịnh và đóng băng nào? Bản chất toán học đằng sau sự thất bại của Perceptron trước bài toán XOR và định lý hội tụ Novikoff phản ánh quy luật tiến hóa gì trong thiết kế thuật toán?", "Câu hỏi CH1 (Lịch sử & Tiến trình):")
    p_bullet(doc, "Làm thế nào để kiểm chứng toán học tính đúng đắn tuyệt đối của thuật toán lan truyền ngược tự lập trình bằng NumPy Scratch so với các thư viện tiêu chuẩn công nghiệp (PyTorch, Keras)? Làm sao để triệt tiêu 100% rủi ro rò rỉ dữ liệu (data leakage) trong các bài toán bảng có độ mất cân bằng lớp nghiêm trọng?", "Câu hỏi CH2 (Học máy Cơ bản & Parity):")
    p_bullet(doc, "Bằng cách nào toán học tích chập 2D và kỹ thuật ma trận hóa im2col GEMM giúp tối ưu hóa bộ nhớ đệm phần cứng? Cơ chế bản đồ kích hoạt lớp có trọng số Grad-CAM dẫn xuất toán học như thế nào để cung cấp bằng chứng giải thích trực quan cho các quyết định chẩn đoán hình ảnh y tế và phát hiện mẫu nến tài chính 2D?", "Câu hỏi CH3 (Mạng Tích chập CNN & Thị giác):")
    p_bullet(doc, "Vì sao hiện tượng suy giảm gradient (vanishing gradient) xuất hiện tất yếu trong mạng Vanilla RNN khi áp dụng giải tích chuỗi Jacobian qua thời gian (BPTT)? Kiến trúc Băng chuyền Lỗi Bất biến (CEC) của Hochreiter & Schmidhuber trong ô nhớ LSTM giải quyết triệt để vấn đề này trên phương diện toán học ra sao?", "Câu hỏi CH4 (Mạng Hồi quy RNN/LSTM & Chuỗi thời gian):")
    p_bullet(doc, "Làm thế nào để kết hợp Đồ thị Tri thức ngữ nghĩa (RDF/OWL) với cơ chế tìm kiếm lai (BM25 + Dense Vector Search + RRF k=60) nhằm triệt tiêu hoàn toàn ảo giác của LLM? Động cơ GraphRAG đa bước có khả năng trả lời chính xác các câu hỏi lâm sàng và tài chính phức tạp tới mức độ nào?", "Câu hỏi CH5 (Knowledge Graph & GraphRAG):")
    p_bullet(doc, "Toán học của toán tử Laplace-Beltrami rời rạc và ma trận chuẩn hóa đối xứng L_sym dẫn xuất ra thuật toán GCN của Kipf & Welling như thế nào? Bằng chứng toán học nào giải thích hiện tượng quá làm mịn (over-smoothing) thông qua năng lượng Dirichlet và phép thử đẳng cấu 1-WL đặt ra giới hạn gì cho mạng GNN sâu?", "Câu hỏi CH6 (Học sâu Đồ thị Deep Graph):")
    p_bullet(doc, "Làm thế nào để phối hợp đa tác tử LLM tự chủ theo lý thuyết trò chơi và quy trình hội chẩn lâm sàng? Cơ chế Cổng Đồng thuận Bayesian (Bayesian Consensus Gate với ngưỡng tau = 0.85) và Đường ống Phòng vệ 4 Tầng (4-Tier Guardrails) có thể triệt tiêu 100% các rủi ro kê đơn sai lệch và số liệu mâu thuẫn như thế nào?", "Câu hỏi CH7 (Hệ Đa Tác tử MAS & An toàn):")

    h_sec(doc, "4. Đối tượng và phạm vi nghiên cứu Đa miền (Dual Domains)")
    p_body(doc, "Tiểu luận không dừng lại ở các bài toán đồ chơi (toy datasets) mà áp dụng trực tiếp các phương pháp nghiên cứu trên hai miền dữ liệu thực nghiệm quy mô lớn:")
    p_bullet(doc, "Bao gồm bộ dữ liệu Pima Indians Diabetes (768 ca bệnh thực tế), Bộ dữ liệu giám sát đường huyết liên tục CGM Shanghai (1.440 điểm đo thực nghiệm liên tục trên bệnh nhân đái tháo đường Type 1/2), Bộ dữ liệu ảnh võng mạc tổn thương đáy mắt RetinaMNIST (1.080 ảnh y tế chuẩn hóa), và Cơ sở tri thức đồ thị lâm sàng Neo4j quy mô lớn với hơn 90.000 thực thể và quan hệ điều trị.", "Miền 1: Y tế Thông minh & Bệnh lý Chuyển hóa (Metabolic Healthcare):")
    p_bullet(doc, "Bao gồm bộ dữ liệu tín dụng tiêu dùng Lending Club thực tế (36.162 khoản vay cá nhân với 24 đặc trưng tài chính khắt khe), Chuỗi dữ liệu giá giao dịch đa thị trường có tần suất cao (VN-Index đại diện thị trường cận biên Việt Nam, S&P 500 đại diện thị trường phát triển Mỹ, Bitcoin đại diện tài sản số toàn cầu) giai đoạn 2018–2024, và Đồ thị tương quan ngành VN30 phục vụ phân tích rủi ro hệ thống.", "Miền 2: Kinh tế & Định lượng Tài chính Đa thị trường (Quantitative Finance):")

    h_sec(doc, "5. Phương pháp nghiên cứu và quy trình thực nghiệm 4 bước")
    p_body(doc, "Toàn bộ công trình được thực thi theo Quy trình Thực nghiệm Chuẩn hóa 4 Bước khép kín:")
    p_bullet(doc, "Thu thập, làm sạch, mã hóa biến phân loại (Target Encoding, One-Hot), xử lý giá trị ngoại lai bằng winsorization, chuẩn hóa RobustScaler/StandardScaler hoàn toàn bên trong từng fold cross-validation nhằm ngăn chặn rò rỉ dữ liệu tuyệt đối.", "Bước 1 - Tiền xử lý Dữ liệu Chuẩn hóa:")
    p_bullet(doc, "Xây dựng song song mô hình trên 3 khung lập trình (NumPy Scratch, Keras, PyTorch). Huấn luyện bằng các thuật toán tối ưu hóa hiện đại (AdamW, SGD with Momentum, Cosine Annealing Learning Rate Schedule).", "Bước 2 - Huấn luyện & Tối ưu Đa khung:")
    p_bullet(doc, "Thực hiện phép kiểm tra Gradient Parity Check giữa bản Scratch và Autograd với sai số tuyệt đối dưới 10^-7. Đánh giá mô hình bằng Stratified 10-Fold CV, Walk-Forward Time-Series Split, tính toán khoảng tin cậy 95% Bootstrap, vẽ biểu đồ ROC/PR và ma trận nhầm lẫn chuẩn hóa.", "Bước 3 - Đánh giá Đa chiều & Kiểm chứng Parity:")
    p_bullet(doc, "Chuyển giao các mô hình học sâu và hệ đa tác tử thành các dịch vụ suy luận thời gian thực, tích hợp giao diện Web Dashboard cục bộ (Localhost) trực quan, cho phép người dùng kiểm tra từng ca bệnh hoặc từng phiên giao dịch cụ thể.", "Bước 4 - Đóng gói & Triển khai Ứng dụng Web Localhost:")

    if add_figure:
        add_figure(doc, "project01/figures/fig11_radar_model_evaluation.png", 
                   "Hình 0.1. Sơ đồ tổng thể quy trình nghiên cứu thực nghiệm 4 bước từ dữ liệu đến triển khai ứng dụng", width=5.6)

    h_sec(doc, "6. Mười đóng góp học thuật và kỹ thuật chính của công trình")
    p_body(doc, "Tiểu luận mang lại 10 đóng góp khoa học và kỹ thuật rõ nét:")
    p_bullet(doc, "Trình bày dẫn xuất toán học chi tiết cho Định lý Hội tụ Novikoff của Perceptron và Định lý Minsky-Papert (1969) chứng minh giới hạn của mô hình tuyến tính trên hàm logic XOR.", "1. Chứng minh Toán học Lịch sử AI:")
    p_bullet(doc, "Dẫn xuất đầy đủ phân rã Bias-Variance sai số bình phương trung bình, phương trình pháp tuyến OLS/Ridge, đạo hàm hàm mất mát BCE và hệ điều kiện tối ưu KKT của Support Vector Machines.", "2. Nền tảng Giải tích Học máy Cơ bản:")
    p_bullet(doc, "Xây dựng thành công thuật toán lan truyền ngược giải tích từ đầu bằng pure NumPy cho MLP, CNN và LSTM, đối chứng sai lệch ma trận trọng số với Keras và PyTorch đạt độ chính xác dưới 10^-7.", "3. Kiểm chứng Tương đương Đạo hàm Tuyệt đối (Parity Check):")
    p_bullet(doc, "Cài đặt thuật toán im2col kết hợp GEMM tăng tốc tích chập gấp 10-50 lần so với vòng lặp lồng nhau; tích hợp kỹ thuật Grad-CAM bóc tách trực quan vùng tổn thương đáy mắt và mẫu hình nến tài chính 2D.", "4. Thuật toán im2col và Giải thích Grad-CAM:")
    p_bullet(doc, "Chứng minh toán học cơ chế Băng chuyền Lỗi Bất biến CEC của LSTM giúp triệt tiêu hiện tượng vanishing gradient theo giải tích Jacobian chuỗi thời gian.", "5. Dẫn xuất Toán học CEC trong Mạng Hồi quy:")
    p_bullet(doc, "Thiết lập hệ thống mô phỏng đầu tư thực tế tích hợp đầy đủ chi phí giao dịch (0.15%), thuế (0.1%) và trượt giá (0.05%), chứng minh các chiến lược học sâu tạo alpha thực chất vượt trội Buy & Hold.", "6. Công cụ Kiểm thử Định lượng Thực tế sau Phí:")
    p_bullet(doc, "Triển khai cơ chế truy hồi thông tin lai 3 thành phần (BM25 + Dense HNSW + RRF k=60) kết hợp bản thể học Đồ thị Tri thức Neo4j, đạt điểm Ragas Faithfulness 1.000 tuyệt đối.", "7. Động cơ GraphRAG Ngữ nghĩa Chuẩn xác:")
    p_bullet(doc, "Dẫn xuất toán tử Laplace chuẩn hóa đối xứng L_sym, chứng minh hiện tượng quá làm mịn (over-smoothing) thông qua năng lượng Dirichlet và phân tích giới hạn biểu diễn qua phép thử đẳng cấu 1-WL.", "8. Lý thuyết và Thực nghiệm Học sâu trên Đồ thị:")
